//! Tokens of the host's own surfaces, generated from `DESIGN.md`: the chrome, a dialog's surface,
//! scrim and elevation, the panel's attachment to its frame and the host's focus style.
//! `deny.toml` lets only the `host` crate depend on this one
//! (specs/007-host-visual-design/research.md, R6).

// Generated by `cargo xtask design` and compared byte for byte, so rustfmt leaves it alone
#[rustfmt::skip]
mod generated;

pub use design_tokens::{Appearance, Rgb, Theme};
pub use generated::COMPONENTS;
pub use generated::elevation::Shadow;

use design_tokens::raw::{RoleDef, resolve};

fn role(name: &str) -> &'static RoleDef {
    generated::ROLES
        .iter()
        .find(|role| role.name == name)
        .expect("a host surface DESIGN.md defines")
}

fn color(name: &str, appearance: &Appearance, theme: Theme) -> Rgb {
    resolve(role(name), appearance, theme).0
}

/// The host's bar: only a host dialog covers it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ChromeColors {
    pub surface: Rgb,
    pub text: Rgb,
}

/// A host dialog: its surface, the scrim over every host window, and its shadow.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DialogStyle {
    pub surface: Rgb,
    pub scrim: Rgb,
    pub scrim_opacity: f64,
    pub shadow: Option<Shadow>,
}

/// The panel a frame opens, attached to it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PanelStyle {
    pub surface: Rgb,
    pub shadow: Option<Shadow>,
}

/// The host's focus ring.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct FocusStyle {
    pub ring: Rgb,
    /// In pixels; WCAG 2.4.13 asks for an indicator at least 2 px thick.
    pub width: f32,
}

pub fn chrome(appearance: &Appearance, theme: Theme) -> ChromeColors {
    let text = design_tokens::tone(design_tokens::Tone::Default, appearance, theme).text;
    ChromeColors {
        surface: color("chrome-surface", appearance, theme),
        text,
    }
}

pub fn dialog(appearance: &Appearance, theme: Theme) -> DialogStyle {
    let (scrim, scrim_opacity) = resolve(role("scrim"), appearance, theme);
    DialogStyle {
        surface: color("dialog-surface", appearance, theme),
        scrim,
        scrim_opacity,
        shadow: generated::elevation::DIALOG,
    }
}

pub fn panel_attachment(appearance: &Appearance, theme: Theme) -> PanelStyle {
    PanelStyle {
        surface: color("panel-surface", appearance, theme),
        shadow: generated::elevation::PANEL,
    }
}

pub fn focus(appearance: &Appearance, theme: Theme) -> FocusStyle {
    FocusStyle {
        ring: color("focus", appearance, theme),
        width: 2.0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_surface_resolves_in_both_themes() {
        for theme in [Theme::Light, Theme::Dark] {
            let appearance = Appearance::DEFAULT;
            let dialog = dialog(&appearance, theme);
            assert!(dialog.scrim_opacity > 0.0 && dialog.scrim_opacity < 1.0);
            assert!(dialog.shadow.is_some());
            assert!(panel_attachment(&appearance, theme).shadow.is_some());
            assert_eq!(focus(&appearance, theme).width, 2.0);
            let chrome = chrome(&appearance, theme);
            assert!(design_tokens::contrast(chrome.text, chrome.surface) >= 4.5);
        }
    }
}
